<template>
  <q-card
    class="agent-profile-card cursor-pointer"
    :class="{
      'agent-profile-card--disabled': profile.agent.is_enabled === false || inactive,
      'agent-profile-card--system': cardTint === 'system',
      'agent-profile-card--user': cardTint === 'user',
    }"
    flat
    bordered
    @click="$router.push('/doc-net/agents/' + profile.agent.id)"
  >
    <q-card-section>
      <div class="row items-start q-gutter-sm q-mb-sm">
        <div class="agent-avatar-wrapper">
          <q-avatar size="40px" :color="avatarColor" text-color="white" font-size="20px">
            <q-icon name="smart_toy" />
          </q-avatar>
          <q-tooltip v-if="profile.heartbeat_status">
            {{ heartbeatLabel }} · {{ profile.heartbeat_step || '—' }}
            <br v-if="profile.last_heartbeat_at" />
            <span v-if="profile.last_heartbeat_at">{{ heartbeatAgo }}</span>
          </q-tooltip>
          <span v-if="isActive" class="agent-pulse" :class="heartbeatDotClass" />
        </div>
        <div class="col">
          <div class="agent-card-name">{{ profile.agent.name }}</div>
          <div class="text-caption text-grey-6 text-capitalize">{{ profile.role }}</div>
        </div>
        <q-toggle
          v-if="toggleable"
          :model-value="profile.agent.is_enabled !== false"
          :disable="toggleDisabled"
          color="positive"
          size="sm"
          @click.stop
          @update:model-value="$emit('toggle', profile.agent.id, $event)"
        />
        <q-btn
          v-if="!profile.agent.is_system"
          flat
          dense
          round
          icon="more_vert"
          size="sm"
          @click.stop
        >
          <q-menu>
            <q-list dense style="min-width: 120px;">
              <q-item clickable v-close-popup dense @click="$emit('edit', profile.agent.id)">
                <q-item-section side><q-icon name="edit" size="16px" /></q-item-section>
                <q-item-section>{{ $t('docnet_edit') }}</q-item-section>
              </q-item>
              <q-item clickable v-close-popup dense @click="$emit('delete', profile.agent.id)">
                <q-item-section side><q-icon name="delete" size="16px" color="negative" /></q-item-section>
                <q-item-section class="text-negative">{{ $t('docnet_delete') }}</q-item-section>
              </q-item>
            </q-list>
          </q-menu>
        </q-btn>
      </div>

      <!-- Skills -->
      <div v-if="profile.skills_summary?.length" class="row q-gutter-xs q-mb-sm" style="flex-wrap: wrap;">
        <q-chip
          v-for="skill in profile.skills_summary"
          :key="skill"
          size="xs"
          outline
          color="primary"
          :label="formatSkill(skill)"
          dense
        />
      </div>

    </q-card-section>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetAgentProfile } from 'src/@types/docnet';
import { formatRelativeTime } from 'src/utils/docnet/formatting';
import { titleCase } from '../../shared/docnet-labels';

export default defineComponent({
  name: 'AgentProfileCard',

  props: {
    profile: {
      type: Object as PropType<DocNetAgentProfile>,
      required: true,
    },
    toggleable: {
      type: Boolean,
      default: true,
    },
    toggleDisabled: {
      type: Boolean,
      default: false,
    },
    inactive: {
      type: Boolean,
      default: false,
    },
    cardTint: {
      type: String as PropType<'system' | 'user' | ''>,
      default: '',
    },
  },

  emits: ['toggle', 'edit', 'delete'],

  computed: {
    isOrchestrator(): boolean {
      return this.profile.agent.id === 'docbits-orchestrator' || this.profile.agent.name === 'DocBits Orchestrator';
    },

    isActive(): boolean {
      const hs = this.profile.heartbeat_status;
      return hs === 'working' || hs === 'awake' || this.profile.workload_percent > 0;
    },

    heartbeatDotClass(): string {
      const hs = this.profile.heartbeat_status;
      if (hs === 'working') return 'pulse--working';
      if (hs === 'awake') return 'pulse--awake';
      if (hs === 'error') return 'pulse--error';
      return '';
    },

    heartbeatLabel(): string {
      const map: Record<string, string> = {
        sleeping: 'agent_sleeping',
        awake: 'agent_awake',
        working: 'agent_working',
        error: 'agent_error',
      };
      const key = map[this.profile.heartbeat_status || ''];
      return key ? this.$t(key) : this.$t('agent_idle');
    },

    heartbeatAgo(): string {
      if (!this.profile.last_heartbeat_at) return '';
      return formatRelativeTime(this.profile.last_heartbeat_at, this.$t);
    },

    workloadColor(): string {
      if (this.profile.workload_percent >= 80) return 'negative';
      if (this.profile.workload_percent >= 50) return 'orange';
      return 'positive';
    },

    statusColor(): string {
      if (this.isActive) return 'primary';
      return 'blue-grey';
    },

    avatarColor(): string {
      if (this.cardTint === 'system') return 'deep-purple';
      if (this.cardTint === 'user') return 'blue';
      return this.statusColor;
    },

    approvalIcon(): string {
      const map: Record<string, string> = {
        auto: 'flash_on',
        manual: 'person',
        hybrid: 'tune',
      };
      return map[this.profile.approval_mode] || 'help';
    },

    approvalColor(): string {
      const map: Record<string, string> = {
        auto: 'positive',
        manual: 'warning',
        hybrid: 'info',
      };
      return map[this.profile.approval_mode] || 'grey';
    },
  },

  methods: {
    formatSkill(skill: string): string {
      const key = `docnet_skill_${skill}`;
      const translated = this.$t(key);
      return translated && translated !== key ? translated : titleCase(skill);
    },
  },
});
</script>

