<template>
  <div class="docnet-agent-list">
    <!-- Header with Create button -->
    <div class="agent-header row items-center justify-end q-mb-md">
      <div class="agent-legend row items-center">
        <span class="legend-dot legend-dot--system" />
        <span class="text-caption text-grey-7 q-mr-md">{{ $t('docnet_agent_system') }}</span>
        <span class="legend-dot legend-dot--user" />
        <span class="text-caption text-grey-7">{{ $t('docnet_agent_custom') }}</span>
      </div>
      <q-btn
        color="primary"
        icon="add"
        :label="$t('docnet_create_agent')"
        no-caps
        unelevated
        rounded
        @click="showCreateWizard = true"
      />
    </div>

    <!-- Agent Wizard Dialog -->
    <q-dialog v-model="showCreateWizard" persistent>
      <q-card style="min-width: 700px; max-width: 900px; max-height: 90vh;" class="create-agent-dialog">
        <AgentWizard
          :agent="editingAgent"
          :is-edit="!!editingAgent"
          @saved="onAgentSaved"
          @cancel="closeWizard"
        />
      </q-card>
    </q-dialog>

    <div v-if="loading" class="text-center q-pa-xl">
      <q-spinner-dots color="primary" size="40px" />
    </div>

    <div v-else-if="profiles.length === 0" class="text-center q-pa-xl">
      <q-icon name="smart_toy" size="64px" color="grey-5" />
      <p class="q-mt-md text-grey-6">{{ $t('no_agents') }}</p>
    </div>

    <template v-else>
      <!-- Router -->
      <div v-if="routerProfiles.length > 0" class="q-mb-lg">
        <div class="section-label">
          <q-icon name="alt_route" size="16px" class="q-mr-xs" />
          {{ $t('docnet_router') }}
          <q-badge v-if="enabledOrchestratorCount > 1" color="positive" :label="$t('docnet_active')" class="q-ml-sm" />
          <q-badge v-else color="grey" :label="$t('docnet_router_inactive')" class="q-ml-sm" />
        </div>
        <div class="agents-grid">
          <AgentProfileCard
            v-for="profile in routerProfiles"
            :key="profile.agent.id"
            :profile="profile"
            :toggleable="false"
            :inactive="enabledOrchestratorCount <= 1"
            card-tint="system"
          />
        </div>
      </div>

      <!-- Orchestrators -->
      <div v-if="orchestratorProfiles.length > 0" class="q-mb-lg">
        <div class="section-label">
          <q-icon name="account_tree" size="16px" class="q-mr-xs" />
          {{ $t('docnet_orchestrators') }}
        </div>
        <div class="agents-grid">
          <AgentProfileCard
            v-for="profile in orchestratorProfiles"
            :key="profile.agent.id"
            :profile="profile"
            :toggleable="true"
            :toggle-disabled="profile.agent.is_enabled !== false && enabledOrchestratorCount <= 1"
            :card-tint="profile.agent.is_system ? 'system' : 'user'"
            @toggle="onToggle"
            @edit="onEdit"
            @delete="onDelete"
          />
        </div>
      </div>

      <!-- Agents -->
      <div v-if="agentProfiles.length > 0">
        <div class="section-label">
          <q-icon name="smart_toy" size="16px" class="q-mr-xs" />
          {{ $t('docnet_agents') }}
        </div>
        <div class="agents-grid">
          <AgentProfileCard
            v-for="profile in agentProfiles"
            :key="profile.agent.id"
            :profile="profile"
            :toggleable="false"
            :card-tint="profile.agent.is_system ? 'system' : 'user'"
            @edit="onEdit"
            @delete="onDelete"
          />
        </div>
      </div>
    </template>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';

import { useDocNetAgentStore } from 'src/store/DocNet/docnet-agents.store';
import { useAgentsStore } from 'src/store/Settings/agents.store';
import { storeToRefs } from 'pinia';
import AgentProfileCard from './components/AgentProfileCard.vue';
import AgentWizard from 'src/pages/Settings/Components/Agents/AgentWizard.vue';
import AgentApiService from 'src/services/settings/AgentApiService';
import { useUserStore } from 'src/store/User/user_details.store';
import type { DocNetAgentProfile } from 'src/@types/docnet';
import type { Agent } from 'src/@types/agents';

const agentApiService = new AgentApiService();

export default defineComponent({
  name: 'DocNetAgentList',

  components: {
    AgentProfileCard,
    AgentWizard,
  },

  setup() {
    const agentStore = useDocNetAgentStore();
    const { profiles, loading } = storeToRefs(agentStore);
    return { agentStore, profiles, loading };
  },

  data() {
    return {
      showCreateWizard: false,
      editingAgent: null as Agent | null,
    };
  },

  computed: {
    routerProfiles(): DocNetAgentProfile[] {
      return this.profiles.filter((p) => p.role === 'router');
    },
    orchestratorProfiles(): DocNetAgentProfile[] {
      return this.profiles.filter((p) => p.role === 'orchestrator');
    },
    enabledOrchestratorCount(): number {
      return this.orchestratorProfiles.filter((p) => p.agent.is_enabled !== false).length;
    },
    agentProfiles(): DocNetAgentProfile[] {
      return this.profiles.filter((p) => p.role !== 'router' && p.role !== 'orchestrator');
    },
  },

  async mounted() {
    // Skills drive the "Advanced tool settings" section of the create
    // wizard. Preload so the first open of that dialog renders tools
    // immediately instead of after a round-trip.
    await Promise.allSettled([
      this.agentStore.fetchProfiles(),
      useAgentsStore().fetchSkills(),
    ]);
  },

  methods: {
    async onToggle(agentId: string, enabled: boolean) {
      const profile = this.profiles.find((p) => p.agent.id === agentId);
      if (!profile) return;
      const prev = profile.agent.is_enabled;
      console.log('[DocNet Toggle] START', { agentId, agentName: profile.agent.name, is_system: profile.agent.is_system, enabled, prevEnabled: prev });
      profile.agent.is_enabled = enabled;
      try {
        const userId = useUserStore().getUserId() as string;
        console.log('[DocNet Toggle] Calling API toggle...');
        const response = await agentApiService.toggle(agentId, enabled, userId);
        console.log('[DocNet Toggle] API response:', JSON.stringify(response));
        console.log('[DocNet Toggle] Fetching profiles...');
        await this.agentStore.fetchProfiles(true);
        const updatedProfile = this.profiles.find((p) => p.agent.id === agentId);
        console.log('[DocNet Toggle] After fetchProfiles:', { agentId, is_enabled: updatedProfile?.agent.is_enabled, config_role: updatedProfile?.role });
        notify.success(enabled ? this.$t('agent_enabled') : this.$t('agent_disabled'));
      } catch (err) {
        console.error('[DocNet Toggle] ERROR:', err);
        profile.agent.is_enabled = prev;
        notify.error(this.$t('agent_toggle_failed'));
      }
    },

    async onAgentSaved() {
      this.showCreateWizard = false;
      this.editingAgent = null;
      await this.agentStore.fetchProfiles(true);
      notify.success(this.$t('docnet_agent_created'));
    },

    closeWizard() {
      this.showCreateWizard = false;
      this.editingAgent = null;
    },

    onEdit(agentId: string) {
      const profile = this.profiles.find((p: DocNetAgentProfile) => p.agent.id === agentId);
      if (!profile) return;
      this.editingAgent = profile.agent as Agent;
      this.showCreateWizard = true;
    },

    async onDelete(agentId: string) {
      const profile = this.profiles.find((p: DocNetAgentProfile) => p.agent.id === agentId);
      if (!profile) return;
      this.$q.dialog({
        title: this.$t('delete_agent_title'),
        message: this.$t('delete_agent_confirm', { name: profile.agent.name }),
        cancel: true,
        persistent: true,
      }).onOk(async () => {
        try {
          await agentApiService.remove(agentId);
          await this.agentStore.fetchProfiles(true);
          notify.success(this.$t('docnet_agent_deleted'));
        } catch {
          notify.error(this.$t('docnet_agent_delete_failed'));
        }
      });
    },
  },
});
</script>

